//! Lombok Annotation Support
//!
//! This module provides hover information for Lombok-generated fields and methods.
//! Lombok generates code at compile time through annotation processing, which means
//! these symbols don't exist in the source AST. We detect Lombok annotations and
//! synthesize appropriate hover information.

use hyperion_parser::syntax::{Annotation, AstNode, SyntaxKind};
use hyperion_parser::SyntaxNode;
use tracing::debug;

/// Information about a field generated by Lombok
#[derive(Debug, Clone)]
pub struct LombokField {
    pub name: &'static str,
    pub type_fqn: &'static str,
    pub is_static: bool,
    pub documentation: &'static str,
}

/// A Lombok annotation and the fields it generates
#[derive(Debug)]
struct LombokAnnotation {
    annotation_name: &'static str,
    generated_fields: Vec<LombokField>,
}

/// Registry of known Lombok annotations and their generated symbols
pub struct LombokRegistry {
    annotations: Vec<LombokAnnotation>,
}

impl LombokRegistry {
    /// Create a new registry with all known Lombok annotations
    pub fn new() -> Self {
        let annotations = vec![
            LombokAnnotation {
                annotation_name: "Slf4j",
                generated_fields: vec![LombokField {
                    name: "log",
                    type_fqn: "org.slf4j.Logger",
                    is_static: true,
                    documentation: "Logger instance generated by @Slf4j annotation",
                }],
            },
            LombokAnnotation {
                annotation_name: "Log4j2",
                generated_fields: vec![LombokField {
                    name: "log",
                    type_fqn: "org.apache.logging.log4j.Logger",
                    is_static: true,
                    documentation: "Logger instance generated by @Log4j2 annotation",
                }],
            },
            LombokAnnotation {
                annotation_name: "CommonsLog",
                generated_fields: vec![LombokField {
                    name: "log",
                    type_fqn: "org.apache.commons.logging.Log",
                    is_static: true,
                    documentation: "Logger instance generated by @CommonsLog annotation",
                }],
            },
            LombokAnnotation {
                annotation_name: "Log",
                generated_fields: vec![LombokField {
                    name: "log",
                    type_fqn: "java.util.logging.Logger",
                    is_static: true,
                    documentation: "Logger instance generated by @Log annotation",
                }],
            },
            LombokAnnotation {
                annotation_name: "XSlf4j",
                generated_fields: vec![LombokField {
                    name: "log",
                    type_fqn: "org.slf4j.ext.XLogger",
                    is_static: true,
                    documentation: "Extended logger instance generated by @XSlf4j annotation",
                }],
            },
        ];

        Self { annotations }
    }

    /// Check if an identifier refers to a Lombok-generated field
    ///
    /// # Arguments
    /// * `identifier` - The identifier name (e.g., "log")
    /// * `enclosing_class` - The class declaration node
    ///
    /// # Returns
    /// The Lombok field info if this is a generated field, None otherwise
    pub fn resolve_lombok_field(
        &self,
        identifier: &str,
        enclosing_class: &SyntaxNode,
    ) -> Option<LombokField> {
        // Check if the class has any Lombok annotations
        let class_annotations = self.extract_class_annotations(enclosing_class);

        debug!(
            "Checking for Lombok field '{}' in class with {} annotations",
            identifier,
            class_annotations.len()
        );

        for annotation_name in class_annotations {
            // Find matching Lombok annotation in registry
            for lombok_ann in &self.annotations {
                if annotation_name == lombok_ann.annotation_name
                    || annotation_name.ends_with(&format!(".{}", lombok_ann.annotation_name))
                {
                    // Found matching annotation - check if identifier matches a generated field
                    for field in &lombok_ann.generated_fields {
                        if field.name == identifier {
                            debug!(
                                "Resolved '{}' as Lombok-generated field from @{}",
                                identifier, lombok_ann.annotation_name
                            );
                            return Some(field.clone());
                        }
                    }
                }
            }
        }

        None
    }

    /// Extract annotation names from a class declaration
    ///
    /// In Java AST, class annotations are typically in a MODIFIER_LIST sibling
    /// adjacent to CLASS_DECL. We only read annotations directly attached to the
    /// class declaration and avoid descending into members.
    fn extract_class_annotations(&self, class_node: &SyntaxNode) -> Vec<String> {
        let mut annotations = Vec::new();

        // Check direct modifier children first.
        for child in class_node.children() {
            if child.kind() == SyntaxKind::MODIFIER_LIST {
                for modifier in child.children() {
                    if modifier.kind() == SyntaxKind::ANNOTATION {
                        if let Some(annotation) = Annotation::cast(modifier) {
                            if let Some(name) = annotation.name() {
                                annotations.push(name.as_string());
                            }
                        }
                    }
                }
            }
        }

        // Also check immediately preceding modifier list sibling.
        let mut prev = class_node.prev_sibling();
        while let Some(node) = prev {
            if node.kind() == SyntaxKind::MODIFIER_LIST {
                for modifier in node.children() {
                    if modifier.kind() == SyntaxKind::ANNOTATION {
                        if let Some(annotation) = Annotation::cast(modifier) {
                            if let Some(name) = annotation.name() {
                                annotations.push(name.as_string());
                            }
                        }
                    }
                }
                break;
            }

            // Stop at the first non-modifier sibling to avoid leaking member annotations.
            if node.kind() != SyntaxKind::MODIFIER {
                break;
            }

            prev = node.prev_sibling();
        }

        annotations
    }
}

impl Default for LombokRegistry {
    fn default() -> Self {
        Self::new()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::navigation::ast_queries::find_enclosing_class;
    use hyperion_parser::{Lexer, Parser};

    fn parse_java(source: &str) -> SyntaxNode {
        let tokens = Lexer::new(source).collect();
        let (green_node, _errors) = Parser::parse(tokens);
        SyntaxNode::new_root(green_node)
    }

    #[test]
    fn test_slf4j_annotation() {
        let source = r#"
            package com.example;
            import lombok.extern.slf4j.Slf4j;

            @Slf4j
            public class Service {
                public void execute() {
                    log.info("test");
                }
            }
        "#;

        let root = parse_java(source);
        let registry = LombokRegistry::new();

        // Find the class node
        let class_node = root
            .descendants()
            .find(|n| n.kind() == SyntaxKind::CLASS_DECL)
            .expect("Should find class");

        // Try to resolve "log" field
        let field = registry.resolve_lombok_field("log", &class_node);
        assert!(field.is_some(), "Should resolve log field");

        let field = field.unwrap();
        assert_eq!(field.name, "log");
        assert_eq!(field.type_fqn, "org.slf4j.Logger");
        assert!(field.is_static);
    }

    #[test]
    fn test_log4j2_annotation() {
        let source = r"
            @Log4j2
            public class Service { }
        ";

        let root = parse_java(source);
        let registry = LombokRegistry::new();

        let class_node = root
            .descendants()
            .find(|n| n.kind() == SyntaxKind::CLASS_DECL)
            .unwrap();

        let field = registry.resolve_lombok_field("log", &class_node);
        assert!(field.is_some());

        let field = field.unwrap();
        assert_eq!(field.type_fqn, "org.apache.logging.log4j.Logger");
    }

    #[test]
    fn test_no_lombok_annotation() {
        let source = r"
            public class Service {
                private Logger log = LoggerFactory.getLogger(Service.class);
            }
        ";

        let root = parse_java(source);
        let registry = LombokRegistry::new();

        let class_node = root
            .descendants()
            .find(|n| n.kind() == SyntaxKind::CLASS_DECL)
            .unwrap();

        let field = registry.resolve_lombok_field("log", &class_node);
        assert!(
            field.is_none(),
            "Should not resolve without Lombok annotation"
        );
    }

    #[test]
    fn test_wrong_field_name() {
        let source = r"
            @Slf4j
            public class Service { }
        ";

        let root = parse_java(source);
        let registry = LombokRegistry::new();

        let class_node = root
            .descendants()
            .find(|n| n.kind() == SyntaxKind::CLASS_DECL)
            .unwrap();

        let field = registry.resolve_lombok_field("logger", &class_node);
        assert!(
            field.is_none(),
            "Should not resolve 'logger' - @Slf4j generates 'log'"
        );
    }

    #[test]
    fn test_find_enclosing_class() {
        let source = r"
            public class Outer {
                public void method() {
                    int x = 0;
                }
            }
        ";

        let root = parse_java(source);

        // Find a node inside the method
        let var_node = root
            .descendants()
            .find(|n| n.kind() == SyntaxKind::LOCAL_VAR_DECL)
            .unwrap();

        let class_node = find_enclosing_class(&var_node);
        assert!(class_node.is_some(), "Should find enclosing class");
        assert_eq!(class_node.unwrap().kind(), SyntaxKind::CLASS_DECL);
    }
}
